namespace DtHub.Core.Papycha;

/// <summary>
/// Which DOFUS Touch ids answer which Papycha page, so that the names can
/// be read from the game at runtime in the player's language. Numbers only
/// (and Papycha's own series names as keys): nothing from the game is
/// embedded, see AGENTS.md.
///
/// Generated by build/touch-ids/touch_ids.py, never edited by hand.
/// </summary>
public sealed record TouchIdTable
{
    /// <summary>Papycha quest id to game quest ids, in display order.</summary>
    public Dictionary<int, int[]> Quests { get; init; } = [];

    /// <summary>Papycha dungeon id to game ids.</summary>
    public Dictionary<int, TouchDungeonIds> Dungeons { get; init; } = [];

    /// <summary>Papycha series name to game achievement id.</summary>
    public Dictionary<string, int> Series { get; init; } = [];

    /// <summary>
    /// Papycha quest id to the game achievement it belongs to, for quests
    /// Papycha files under no series.
    /// </summary>
    public Dictionary<int, int> Links { get; init; } = [];
}

/// <summary>
/// The game dungeons of a Papycha page (two for a lair: Sombre, then
/// Céleste). <paramref name="Monster"/> is the boss whose name the page
/// carries when the game has no dungeon of that name (Moon, Le Chouque,
/// Ul'Khan, Mucane); zero otherwise.
/// </summary>
public sealed record TouchDungeonIds(int[] Dungeons, int Monster = 0);
